import PQueue from 'p-queue';

const queue = new PQueue({concurrency: 8});   // workers: 8 tasks in flight

export function submit(job) {
  queue.add(() => process(job));              // buffered; no await (settles on completion)
}

setInterval(() => metrics.gauge('queue_backlog', queue.size + queue.pending), 5000);

